__NUXT_JSONP__("/anticorrupcion/eventos/multilateralismo_la_mejor_solucion_global_angela_merkel", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{post:{slug:"multilateralismo_la_mejor_solucion_global_angela_merkel",title:"Multilateralismo, la mejor solución global: Angela Merkel",date:"2019-04-30T21:27:04.043Z",img:"https:\u002F\u002Fucarecdn.com\u002F814cc41a-b91d-45cf-918a-b3ecc3568ec4\u002F",autor:"Ethos",category:"anticorrupcion",extracto:"La canciller alemana Angela Merkel llamó a crear un “frente común” para tener un enfoque multilateral en los ámbitos de interés mundial. Durante su discurso en el Global Solutions Summit de Berlín, Merkel afirmó que para eso no basta con actuar desde la política, sino que se requiere también de una sociedad civil fuerte.",toc:[],body:{type:"root",children:[{type:b,tag:c,props:{},children:[{type:a,value:"La canciller alemana Angela Merkel llamó a crear un “frente común” para tener un "},{type:b,tag:d,props:{},children:[{type:a,value:"enfoque multilateral en los ámbitos de interés mundial"}]},{type:a,value:". Durante su discurso en el "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.global-solutions.international\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Global Solutions Summit"}]},{type:a,value:" de Berlín, Merkel afirmó que para eso no basta con actuar desde la política, sino que se "},{type:b,tag:d,props:{},children:[{type:a,value:"requiere también de una sociedad civil fuerte"}]},{type:a,value:". "}]},{type:a,value:j},{type:b,tag:c,props:{},children:[{type:a,value:"Con ese objetivo, el Global Solutions Summit reunió a investigadores, políticos y empresarios de 120 países, quienes analizaron los problemas más apremiantes que enfrentan las naciones. José Luis Chicoma, director general de Ethos, fue parte de ese grupo de expertos en políticas públicas, que "},{type:b,tag:d,props:{},children:[{type:a,value:"combinaron su experiencia y conocimientos para elaborar propuestas ante la urgente problemática"}]},{type:a,value:" en los ámbitos políticos, ambientales y sociales."}]},{type:a,value:j},{type:b,tag:c,props:{},children:[{type:a,value:"Entre los asistentes también se encontraban altos funcionarios del gobierno alemán y de la Unión Europea; así como Naoyuki Yoshino, presidente del T20 en Japón. "}]},{type:a,value:j},{type:b,tag:c,props:{},children:[{type:a,value:"El encuentro promovió el diálogo entre líderes políticos, investigadores, responsables de las políticas públicas, líderes empresariales y organizaciones de la sociedad civil, con la finalidad de "},{type:b,tag:d,props:{},children:[{type:a,value:"hacer recomendaciones en temas de gran alcance del G20"}]},{type:a,value:", como desarrollo, financiamiento de infraestructuras, comercio, cambio climático, cohesión social, cooperación con naciones africanas, poblaciones envejecidas, entre otros."}]},{type:a,value:j},{type:b,tag:c,props:{},children:[{type:a,value:"Además, los expertos hicieron hincapié en la importancia del contexto que brindan los procesos sociales y económicos, así como "},{type:b,tag:d,props:{},children:[{type:a,value:"las implicaciones de un mundo económicamente vinculado"}]},{type:a,value:" en el que el rendimiento económico crece, pero muchas comunidades se sienten excluidas."}]},{type:a,value:j},{type:b,tag:c,props:{},children:[{type:a,value:"El Global Solutions Summit se lleva a cabo cada año y es organizado por la Global Solutions Initiative Foundation. Se trata de "},{type:b,tag:d,props:{},children:[{type:a,value:"una red global de "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" que contribuyen a dar una mayor continuidad e impacto a las estrategias del G20"}]},{type:a,value:". Al encuentro acudieron representantes de "},{type:b,tag:k,props:{},children:[{type:a,value:l}]},{type:a,value:" como "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.brookings.edu\u002Fes\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"The Brookings Institution"}]},{type:a,value:m},{type:b,tag:e,props:{href:"http:\u002F\u002Fbruegel.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Bruegel"}]},{type:a,value:m},{type:b,tag:e,props:{href:"http:\u002F\u002Fwww.cari.org.ar\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"CARI"}]},{type:a,value:" (Argentina), "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.cigionline.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"CIGI"}]},{type:a,value:" (Canadá), "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.cippec.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"CIPPEC"}]},{type:a,value:" (Argentina), Ethos (México), entre otros."}]}]},dir:"\u002Feventos",path:"\u002Feventos\u002Fmultilateralismo_la_mejor_solucion_global_angela_merkel",extension:".md",createdAt:"2023-06-19T05:12:00.569Z",updatedAt:"2022-08-26T15:42:55.712Z"}}],fetch:{},mutations:[]}}("text","element","p","strong","a","nofollow","noopener","noreferrer","_blank","\n","em","think tanks"," (Estados Unidos), ")));